373	+/**
374	+ * The minimap's fog (§3): every tile starts hidden, and tiles within the sight radius of the player's ship are
375	+ * revealed for good as it sails. Terrain is public content, so this is presentation only, not a security boundary
376	+ * (§16); ships are filtered by the server.
377	+ */
378	+export class FogOfWar {
379	+  private readonly revealed: Uint8Array;
380	+  private count = 0;
381	+  private lastTile = -1;
382	+
383	+  constructor(
384	+    readonly widthTiles: number,
385	+    readonly heightTiles: number,
386	+    readonly radiusTiles: number,
387	+  ) {
388	+    this.revealed = new Uint8Array(widthTiles * heightTiles);
389	+  }
390	+
391	+  get revealedCount(): number {
392	+    return this.count;
393	+  }
394	+
395	+  isRevealed(tileX: number, tileY: number): boolean {
396	+    return this.revealed[tileY * this.widthTiles + tileX] === 1;
397	+  }
398	+
399	+  /** Reveals the disc around a tile and returns the tiles it newly revealed, as `[tileX, tileY]` pairs. */
400	+  revealAround(tileX: number, tileY: number): [number, number][] {
401	+    const centre = tileY * this.widthTiles + tileX;
402	+    if (centre === this.lastTile) return [];
403	+    this.lastTile = centre;
404	+    const fresh: [number, number][] = [];
405	+    const radius = this.radiusTiles;
406	+    for (let dy = -radius; dy <= radius; dy++) {
407	+      for (let dx = -radius; dx <= radius; dx++) {
408	+        if (dx * dx + dy * dy > radius * radius) continue;
409	+        const x = tileX + dx;
410	+        const y = tileY + dy;
411	+        if (x < 0 || y < 0 || x >= this.widthTiles || y >= this.heightTiles) continue;
412	+        const index = y * this.widthTiles + x;
413	+        if (this.revealed[index] === 1) continue;
414	+        this.revealed[index] = 1;
415	+        this.count++;
416	+        fresh.push([x, y]);
417	+      }
418	+    }
419	+    return fresh;
420	+  }
421	+}
