2567	+    subUnitsPerTile: SUB_UNITS_PER_TILE,
2568	+    terrain,
2569	+    islands: source.islands,
2570	+    docks,
2571	+    spawnSlots: source.spawnSlots,
2572	+  };
2573	+}
