2578	+  );
2579	+}
2580	+
2581	+/** The side of an island a tile lies on (N, E, S or W), from its offset to the island rectangle's centre. */
2582	+function sideOf(island: IslandSource, tileX: number, tileY: number): Compass {
2583	+  // Doubled offsets keep the rectangle's centre on an integer; scaling by the other side's length makes a long thin
2584	+  // island still read its ends as its ends.
2585	+  const dx = (2 * tileX + 1 - (2 * island.tileX + island.widthTiles)) * island.heightTiles;
