2630	+/**
2631	+ * Octile path costs for one tile step, in sub-units: straight is a tile's side, diagonal its side times √2, rounded to
2632	+ * the nearest integer by an integer square root (no floating-point `Math.sqrt` in the pure packages). For 256
2633	+ * sub-units a tile, 256 and 362.
2634	+ */
2635	+export function octileStepCosts(subUnitsPerTile: number): { readonly straight: number; readonly diagonal: number } {
2636	+  const square = 2 * subUnitsPerTile * subUnitsPerTile;
2637	+  let root = 0;
2638	+  while ((root + 1) * (root + 1) <= square) root++;
2639	+  // Round half up: √square ≥ root + ½ exactly when square − root² > root.
2640	+  return { straight: subUnitsPerTile, diagonal: square - root * root > root ? root + 1 : root };
