2650	+  if (!isNavigable(map, fromX, fromY)) return costs;
2651	+  const step = octileStepCosts(map.subUnitsPerTile);
2652	+  const heap = new MinHeap();
2653	+  const start = fromY * width + fromX;
2654	+  costs[start] = 0;
2655	+  heap.push(0, start);
2656	+  while (heap.size > 0) {
