2874	+  private readonly indexes: number[] = [];
2875	+
2876	+  get size(): number {
2877	+    return this.costs.length;
2878	+  }
2879	+
2880	+  push(cost: number, index: number): void {
2881	+    this.costs.push(cost);
2882	+    this.indexes.push(index);
2883	+    let child = this.costs.length - 1;
2884	+    while (child > 0) {
2885	+      const parent = (child - 1) >> 1;
2886	+      if (this.costs[parent]! <= cost) break;
