2900	+      for (;;) {
2901	+        const left = 2 * parent + 1;
2902	+        const right = left + 1;
2903	+        let smallest = parent;
2904	+        if (left < this.costs.length && this.costs[left]! < this.costs[smallest]!) smallest = left;
