4603	+/** Canvas pixels as RGBA rows, read from a real screenshot of the canvas. */
4604	+async function canvasPixels(page: Page, points: readonly { x: number; y: number }[], radius: number): Promise<[number, number, number][][]> {
4605	+  const png = await page.locator("#game canvas").screenshot();
4606	+  return page.evaluate(
4607	+    async ({ base64, points, radius }) => {
4608	+      const blob = await (await fetch(`data:image/png;base64,${base64}`)).blob();
4609	+      const bitmap = await createImageBitmap(blob);
4610	+      const canvas = new OffscreenCanvas(bitmap.width, bitmap.height);
4611	+      const context = canvas.getContext("2d")!;
4612	+      context.drawImage(bitmap, 0, 0);
4613	+      return points.map(({ x, y }) => {
4614	+        const pixels: [number, number, number][] = [];
4615	+        for (let dy = -radius; dy <= radius; dy++) {
4616	+          for (let dx = -radius; dx <= radius; dx++) {
4617	+            const px = x + dx;
4618	+            const py = y + dy;
4619	+            if (px < 0 || py < 0 || px >= bitmap.width || py >= bitmap.height) continue;
4620	+            const [r, g, b] = context.getImageData(px, py, 1, 1).data;
4621	+            pixels.push([r!, g!, b!]);
4622	+          }
4623	+        }
4624	+        return pixels;
4625	+      });
4626	+    },
4627	+    { base64: png.toString("base64"), points, radius },
4628	+  );
4629	+}
