4631	+function near(pixel: [number, number, number], color: string, tolerance = 24): boolean {
4632	+  const want = Number.parseInt(color.slice(1), 16);
4633	+  const [r, g, b] = pixel;
4634	+  return Math.abs(r - ((want >> 16) & 0xff)) <= tolerance && Math.abs(g - ((want >> 8) & 0xff)) <= tolerance && Math.abs(b - (want & 0xff)) <= tolerance;
4635	+}
