4641	+export async function shipsOnCanvas(page: Page): Promise<string[]> {
4642	+  const drawn = await drawnShips(page);
4643	+  const pixels = await canvasPixels(page, drawn, 0);
4644	+  return drawn.filter((ship, index) => near(pixels[index]![0]!, ship.color)).map((ship) => ship.id).sort();
