4653	+/**
4654	+ * Whether a ship's colour shows anywhere within a few pixels of where a ship at world position (x, y) sub-units would
4655	+ * be drawn on this page's canvas.
4656	+ */
4657	+export async function colourAt(page: Page, x: number, y: number, color: string): Promise<boolean> {
4658	+  const scroll = await camera(page);
4659	+  const point = { x: Math.round(x * PIXELS_PER_SUB_UNIT - scroll.x), y: Math.round(y * PIXELS_PER_SUB_UNIT - scroll.y) };
4660	+  const [pixels] = await canvasPixels(page, [point], 4);
4661	+  return pixels!.some((pixel) => near(pixel, color));
