4664	+const TILE_PIXELS = 16;
4665	+const hex = (color: number) => `#${color.toString(16).padStart(6, "0")}`;
4666	+
4667	+/**
4668	+ * The share, from 0 to 1, of a tile's pixels on this page's canvas within a few levels of a palette colour: its 15 × 15
4669	+ * interior, placed through the camera's scroll. Reads a real screenshot of the canvas, so it checks that the tile map
4670	+ * is drawn, not what the scene meant to draw.
4671	+ */
4672	+export async function tileColourShare(page: Page, tileX: number, tileY: number, color: number): Promise<number> {
4673	+  const scroll = await camera(page);
4674	+  const centre = { x: tileX * TILE_PIXELS + TILE_PIXELS / 2 - scroll.x, y: tileY * TILE_PIXELS + TILE_PIXELS / 2 - scroll.y };
4675	+  const [pixels] = await canvasPixels(page, [centre], TILE_PIXELS / 2 - 1);
4676	+  return pixels!.filter((pixel) => near(pixel, hex(color))).length / pixels!.length;
4677	+}
