4682	+ */
4683	+export async function minimapShows(page: Page, tiles: readonly { tileX: number; tileY: number }[], color: number): Promise<boolean[]> {
4684	+  const [left, top, scale] = ((await page.getByTestId("game").getAttribute("data-minimap")) ?? "").split(",").map(Number);
4685	+  const points = tiles.map(({ tileX, tileY }) => ({ x: Math.floor(left! + (tileX + 0.5) * scale!), y: Math.floor(top! + (tileY + 0.5) * scale!) }));
4686	+  const pixels = await canvasPixels(page, points, 0);
4687	+  return pixels.map(([pixel]) => near(pixel!, hex(color)));
4688	+}
