4711	+/** Holds the keys of a keyboard helm, sending only changes. */
4712	+class Keys {
4713	+  private readonly down = new Set<string>();
4714	+
4715	+  constructor(private readonly page: Page) {}
4716	+
4717	+  async set(key: string, pressed: boolean): Promise<void> {
4718	+    if (pressed === this.down.has(key)) return;
4719	+    if (pressed) {
4720	+      await this.page.keyboard.down(key);
4721	+      this.down.add(key);
4722	+    } else {
4723	+      await this.page.keyboard.up(key);
4724	+      this.down.delete(key);
4725	+    }
4726	+  }
4727	+
4728	+  async releaseAll(): Promise<void> {
4729	+    for (const key of [...this.down]) await this.set(key, false);
4730	+  }
4731	+}
