4733	+export interface SailOptions {
4734	+  /** Stop once the ship is this close to the target, in sub-units. */
4735	+  readonly within?: number;
4736	+  /** Or once this holds. */
4737	+  readonly until?: () => Promise<boolean>;
4738	+  readonly timeoutMs?: number;
4739	+  /** Called with every readout on the way, for checks along the route. */
4740	+  readonly onReadout?: (ship: Readout) => void;
4741	+}
4742	+
4743	+/**
4744	+ * Sails a page's ship toward a world position with the keyboard only, steering from the HUD's authoritative readout:
4745	+ * left or right toward the bearing, up when roughly on course and below the wanted speed, down when too fast. The
4746	+ * wanted speed falls as the target nears, so the ship arrives slowly.
4747	+ */
4748	+export async function sailTo(page: Page, target: { x: number; y: number }, options: SailOptions = {}): Promise<Readout> {
4749	+  const id = await selfId(page);
4750	+  const keys = new Keys(page);
4751	+  const deadline = Date.now() + (options.timeoutMs ?? 30_000);
4752	+  try {
4753	+    for (;;) {
4754	+      const ship = await readout(page, id);
4755	+      if (ship === undefined) throw new Error("own ship missing from the HUD");
4756	+      options.onReadout?.(ship);
4757	+      const dx = target.x - ship.x;
4758	+      const dy = target.y - ship.y;
4759	+      const distance = Math.hypot(dx, dy);
4760	+      if (options.within !== undefined && distance <= options.within) return ship;
4761	+      if (options.until !== undefined && (await options.until())) return ship;
4762	+      if (Date.now() > deadline) throw new Error(`did not reach ${target.x},${target.y} (at ${ship.x},${ship.y})`);
4763	+      const bearing = Math.round((Math.atan2(dy, dx) / (2 * Math.PI)) * HEADING_COUNT);
4764	+      const turn = ((((bearing - ship.heading) % HEADING_COUNT) + HEADING_COUNT + HEADING_COUNT / 2) % HEADING_COUNT) - HEADING_COUNT / 2;
4765	+      await keys.set("ArrowRight", turn > 0);
4766	+      await keys.set("ArrowLeft", turn < 0);
4767	+      const wanted = Math.min(64, Math.max(14, (distance / TILE) * 10));
4768	+      const onCourse = Math.abs(turn) <= 4;
4769	+      await keys.set("ArrowUp", onCourse && ship.speed < wanted - 2);
4770	+      await keys.set("ArrowDown", ship.speed > wanted + 8);
4771	+      await page.waitForTimeout(30);
4772	+    }
4773	+  } finally {
4774	+    await keys.releaseAll();
4775	+  }
4776	+}
