127	  }
128	
129	  /**
130	   * The room's own admission check, which also covers `joinById` (no listing filter applies there): the one seat
131	   * carrying the creator's token, then only seats carrying this match's code. Throwing refuses and frees the seat.
132	   */
133	  override onJoin(client: Client, options: unknown): void {
134	    this.admit(options);
135	    this.simulation = addShip(this.config, this.simulation, client.sessionId);
136	    this.gates.set(client.sessionId, new InputGate());
137	    client.view = new StateView();
138	    this.mirror();
139	  }
140	
141	  override onLeave(client: Client): void {
142	    this.simulation = removeShip(this.simulation, client.sessionId);
143	    this.gates.delete(client.sessionId);
144	    client.view?.dispose();
145	    client.view = undefined;
146	    this.mirror();
147	  }
148	
149	  /**
150	   * Test-only (the server's test-placement setting, off by default): puts a player's ship at rest on a navigable tile.
151	   * Visibility follows at once, as after any move.
152	   */
153	  placeShip(sessionId: string, placement: Placement): void {
154	    this.simulation = placeShip(this.config, this.simulation, sessionId, placement);
155	    this.mirror();
156	  }
157	
158	  /** The ship ids a client's view holds, for tests and diagnostics. */
159	  viewedShipIds(sessionId: string): string[] {
160	    const view = this.clients.get(sessionId)?.view;
161	    if (view === undefined) return [];
162	    return [...this.state.ships.values()].filter((ship) => view.has(ship)).map((ship) => ship.id);
163	  }
164	
165	  /** Inputs dropped per client and reason, for tests and diagnostics. */
166	  droppedInputs(sessionId: string): InputGate["dropped"] | undefined {
167	    return this.gates.get(sessionId)?.dropped;
168	  }
169	
170	  private admit(options: unknown): void {
171	    const request = (options ?? {}) as { code?: unknown; createToken?: unknown };
172	    if (request.createToken === undefined) {
173	      if (request.code === this.state.code) return;
174	      if (request.code !== undefined) throw new ServerError(JoinRefusal.NoSuchMatch, NO_SUCH_MATCH_MESSAGE);
175	    } else if (request.code === undefined && this.createToken !== undefined && request.createToken === this.createToken) {
176	      this.createToken = undefined;
177	      return;
178	    }
179	    throw new ServerError(JoinRefusal.CodeRequired, MATCH_CODE_REQUIRED_MESSAGE);
180	  }
181	
182	  private advance(): void {
183	    const frame = this.simulation.frame + 1;
184	    const inputs: Record<string, PlayerInput> = {};
185	    for (const [sessionId, gate] of this.gates) inputs[sessionId] = gate.inputAt(frame);
186	    this.simulation = step(this.config, this.simulation, inputs);
187	    if (isWorldStep(this.simulation.frame)) this.mirror();
188	  }
189	
190	  /** Copies the plain simulation state into the synced schema, then updates what each client may see. */
191	  private mirror(): void {
192	    this.state.frame = this.simulation.frame;
193	    this.state.worldTick = this.simulation.worldTick;
194	    this.state.players = this.simulation.ships.length;
195	    const present = new Set<string>();
196	    for (const ship of this.simulation.ships) {
197	      present.add(ship.id);
198	      let synced = this.state.ships.get(ship.id);
199	      if (synced === undefined) {
200	        synced = new ShipSchema();
201	        synced.id = ship.id;
202	        synced.slot = ship.slot;
203	        this.state.ships.set(ship.id, synced);
204	      }
205	      synced.x = ship.x;
206	      synced.y = ship.y;
207	      synced.heading = ship.heading;
208	      synced.speed = ship.speed;
209	      synced.dock = ship.dock;
210	    }
211	    for (const id of [...this.state.ships.keys()]) if (!present.has(id)) this.state.ships.delete(id);
212	    this.updateViews();
213	  }
214	
215	  /** Each client's view: its own ship and the ships it can see (§3, §16); nothing else is encoded for it. */
216	  private updateViews(): void {
217	    for (const client of this.clients) {
218	      const view = client.view;
219	      if (view === undefined) continue;
220	      const visible = visibleShipIds(this.config, this.simulation, client.sessionId);
221	      for (const [id, ship] of this.state.ships) {
222	        const shown = view.has(ship);
223	        if (visible.has(id) && !shown) view.add(ship);
224	        else if (!visible.has(id) && shown) view.remove(ship);
225	      }
226	    }
227	  }
228	
229	  private async allocateCode(): Promise<string> {
230	    for (let attempt = 0; attempt < 16; attempt++) {
231	      const code = generateMatchCode();
232	      const taken = await matchMaker.query({ name: this.roomName, code });
233	      if (taken.length === 0) return code;
234	    }
235	    throw new ServerError(JoinRefusal.BadRequest, "Could not allocate a match code");
236	  }
237	}
